import SwiftUI
import UIKit
import WidgetKit

/// A horizontal line or upright, upward-scrolling column for a SwiftUI app or widget.
///
/// In an app, pass the text directly. In a widget, pass an entry generated by
/// `timeline(for:from:schedule:)` or the date and schedule of your own entry.
/// VoiceOver reads the full text once.
public struct WidgetMarquee: View {
    private let text: String
    private let date: Date?
    private var nextDate: Date?
    private let schedule: WidgetMarqueeSchedule

    private var axis: MarqueeAxis { schedule.axis }

    @Environment(\.marqueeEdgeFade) private var edgeFade
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Environment(\.isLuminanceReduced) private var reducedLuminance

    /// Creates a marquee for an app. Text that overflows scrolls using a SwiftUI timeline.
    /// Omitting the schedule adapts the number of positions to the length of the text.
    public init(_ text: String, schedule: WidgetMarqueeSchedule? = nil) {
        self.text = text
        self.date = nil
        self.schedule = schedule ?? WidgetMarqueeSchedule(for: text)
    }

    /// Displays a group member in an app. The next pass begins with the other members.
    public init(_ row: WidgetMarqueeGroup.Row) {
        self.init(row.text, schedule: WidgetMarqueeSchedule(row))
    }

    /// Sets the average travel speed, the timing within each pass, and an optional pause between passes.
    public init(
        _ text: String, pointsPerSecond: CGFloat? = nil,
        timing: WidgetMarqueeTiming = .linear, pauseBetweenLoops: TimeInterval = 0, axis: MarqueeAxis = .horizontal
    ) {
        let schedule = WidgetMarqueeSchedule(
            for: text, pointsPerSecond: pointsPerSecond, timing: timing, pauseBetweenLoops: pauseBetweenLoops, axis: axis
        )
        self.init(text, schedule: schedule)
    }

    /// Displays the text at the position scheduled for this widget entry.
    public init(_ entry: WidgetMarqueeEntry) {
        self.init(entry.text, date: entry.date, schedule: entry.schedule)
        self.nextDate = entry.nextDate
    }

    /// Creates a marquee for the entry displayed at `date`.
    ///
    /// The text stays stationary when it fits along the scrolling axis, Reduce Motion
    /// is enabled, or the system displays the widget with reduced luminance.
    public init(_ text: String, date: Date, schedule: WidgetMarqueeSchedule = .init()) {
        self.text = text
        self.date = date
        self.schedule = schedule
    }

    /// Displays a custom widget entry with the supplied travel speed, timing, and pause.
    public init(
        _ text: String, date: Date, pointsPerSecond: CGFloat? = nil,
        timing: WidgetMarqueeTiming = .linear, pauseBetweenLoops: TimeInterval = 0, axis: MarqueeAxis = .horizontal
    ) {
        let schedule = WidgetMarqueeSchedule(
            for: text, pointsPerSecond: pointsPerSecond, timing: timing, pauseBetweenLoops: pauseBetweenLoops, axis: axis
        )
        self.init(text, date: date, schedule: schedule)
    }

    /// Builds a WidgetKit timeline for the supplied text.
    ///
    /// Omitting the schedule adapts the number of positions to the text length.
    /// WidgetKit controls when entries appear and when it requests the next timeline.
    public nonisolated static func timeline(
        for text: String,
        from date: Date = .now,
        schedule: WidgetMarqueeSchedule? = nil
    ) -> Timeline<WidgetMarqueeEntry> {
        let schedule = schedule ?? WidgetMarqueeSchedule(for: text)
        return schedule.timeline(from: date, entryWithNextDate: { date, next in
            WidgetMarqueeEntry(text, date: date, schedule: schedule, nextDate: next)
        })
    }

    /// Builds a widget timeline with an optional speed in points per second, timing profile, and loop pause.
    /// WidgetKit controls when each scheduled position appears.
    public nonisolated static func timeline(
        for text: String, from date: Date = .now, pointsPerSecond: CGFloat? = nil,
        timing: WidgetMarqueeTiming = .linear, pauseBetweenLoops: TimeInterval = 0, axis: MarqueeAxis = .horizontal
    ) -> Timeline<WidgetMarqueeEntry> {
        let schedule = WidgetMarqueeSchedule(
            for: text, pointsPerSecond: pointsPerSecond, timing: timing, pauseBetweenLoops: pauseBetweenLoops, axis: axis
        )
        return timeline(for: text, from: date, schedule: schedule)
    }

    public var body: some View {
        let line = WidgetMarqueeMetrics.line(from: text)
        let textLength = WidgetMarqueeMetrics.contentLength(for: line, axis: axis)
        let label = messageLabel(for: line)
        let alignment: Alignment = axis == .vertical ? .top : .leading

        GeometryReader { viewport in
            let size = viewport.size
            let length = axis == .vertical ? size.height : size.width
            if textLength <= length {
                label.frame(maxWidth: .infinity, maxHeight: .infinity, alignment: alignment)
            } else {
                let edges = edgeFade.resolved(in: length)
                Group {
                    if reduceMotion || reducedLuminance || schedule.passDuration == 0 {
                        label
                            .padding(axis == .vertical ? .top : .leading, edges.headInset)
                            .frame(width: size.width, height: size.height, alignment: alignment)
                    } else if let date {
                        // A generated entry moves toward its successor. The stop entry is already at the head.
                        let target = nextDate ?? date
                        let start = nextDate == nil ? schedule.previousSample(before: date) : date
                        movingLine(label, at: target, textLength: textLength, in: size, headInset: edges.headInset, from: start)
                    } else if schedule.passDuration != nil {
                        TimelineView(.animation) { context in
                            movingLine(label, at: context.date, textLength: textLength, in: size, headInset: edges.headInset)
                        }
                    } else {
                        TimelineView(.periodic(from: Date(timeIntervalSinceReferenceDate: 0), by: schedule.secondsPerStep)) { context in
                            movingLine(label, at: context.date, textLength: textLength, in: size, headInset: edges.headInset,
                                       from: context.date.addingTimeInterval(-schedule.secondsPerStep))
                        }
                    }
                }
                .clipped()
                .modifier(MarqueeEdgeMask(axis: axis, edges: edges))
            }
        }
        .frame(width: axis == .vertical ? WidgetMarqueeMetrics.columnWidth : nil, height: axis == .horizontal ? 22 : nil)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(Text(verbatim: text))
    }

    @ViewBuilder
    private func messageLabel(for line: String) -> some View {
        if axis == .vertical {
            let characters = Array(line)
            VStack(spacing: 0) {
                ForEach(characters.indices, id: \.self) { index in
                    Text(verbatim: String(characters[index]))
                        .lineLimit(1)
                        .frame(width: WidgetMarqueeMetrics.columnWidth, height: WidgetMarqueeMetrics.verticalAdvance)
                }
            }
            .font(Font(WidgetMarqueeMetrics.font))
            .fixedSize()
        } else {
            Text(verbatim: line).font(Font(WidgetMarqueeMetrics.font)).lineLimit(1)
        }
    }

    private func movingLine(
        _ label: some View, at date: Date, textLength: CGFloat, in size: CGSize, headInset: CGFloat, from start: Date? = nil
    ) -> some View {
        let animation = start.flatMap { schedule.entryAnimation(from: $0, to: date) }
        let alignment: Alignment = axis == .vertical ? .top : .leading
        return ZStack(alignment: alignment) {
            ForEach(0..<3, id: \.self) { copy in
                let lane = schedule.position(at: date, copy: copy)
                let shift = (textLength + WidgetMarqueeMetrics.gap) * (1 - CGFloat(lane)) + headInset
                label
                    .fixedSize()
                    .offset(x: axis == .horizontal ? shift : 0, y: axis == .vertical ? shift : 0)
                    .animation(lane == 0 ? nil : animation, value: lane)
                    // A returning copy may skip the offscreen reset entry.
                    // A new identity keeps it from animating backwards across the viewport.
                    .id(schedule.copyCycle(at: date, copy: copy))
                    .transition(.identity)
            }
        }
        .frame(width: size.width, height: size.height, alignment: alignment)
        .environment(\.layoutDirection, .leftToRight)
    }
}

extension WidgetMarqueeSchedule {
    func entryAnimation(from start: Date, to end: Date) -> Animation? {
        let interval = end.timeIntervalSince(start)
        guard interval > 0 else { return nil }
        let linear = Animation.linear(duration: interval)
        guard let pass = passDuration else { return linear }
        guard pass >= interval else { return nil }

        // Copies reset offscreen once per three passes. The distance here is
        // always leftward, including the interval that ends at the loop head.
        var distance = position(at: end, copy: 0) - position(at: start, copy: 0)
        if distance < -1e-12 { distance += 3 }
        guard distance > 1e-12 else { return nil }
        guard timing == .easeInOut else { return linear }

        // Match the motion's slopes at both ends of the actual scheduled
        // interval. Intermediate entries do not restart the easing curve.
        let firstSpeed = speedFactor(at: start, pass: pass)
        let lastSpeed = speedFactor(at: end, pass: pass)
        if let cruiseFactor, firstSpeed == cruiseFactor, lastSpeed == cruiseFactor { return linear }
        let scale = (interval / pass) / (3 * distance)
        let firstControl = min(1, firstSpeed * scale)
        let lastControl = max(0, 1 - lastSpeed * scale)
        return .timingCurve(1.0 / 3, firstControl, 2.0 / 3, lastControl, duration: interval)
    }
}

// The timeline provider and view must use the same layout to convert distance to time.
enum WidgetMarqueeMetrics {
    static let font = UIFont.monospacedSystemFont(ofSize: 14, weight: .regular)
    static let gap: CGFloat = 28
    static let columnWidth: CGFloat = 23
    static let verticalAdvance: CGFloat = 20

    static func contentLength(for line: String, axis: MarqueeAxis) -> CGFloat {
        axis == .vertical ? CGFloat(line.count) * verticalAdvance : textWidth(for: line)
    }

    static func line(from text: String) -> String {
        text.split(omittingEmptySubsequences: false, whereSeparator: \.isNewline).joined(separator: " ")
    }

    static func textWidth(for line: String) -> CGFloat {
        ceil((line as NSString).size(withAttributes: [.font: font]).width)
    }

    static func repeatWidth(for line: String) -> CGFloat {
        textWidth(for: line) + gap
    }

    static func liveRepeatWidth(for line: String) -> CGFloat {
        ((line + "    ") as NSString).size(withAttributes: [.font: font]).width
    }
}
